      AND COALESCE(dl.submitted, false)
      AND COALESCE(dl.is_travel_day, false) = false
      AND dl.workout1 AND dl.workout2 AND dl.water AND dl.steps
      AND dl.no_sugar AND dl.reading AND dl.diet
    LIMIT 1
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'first_perfect_day')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.check_ins c
    WHERE c.user_id = uid AND c.photo_url IS NOT NULL AND TRIM(c.photo_url) <> ''
  ) OR EXISTS (
    SELECT 1 FROM public.body_stats b
    WHERE b.user_id = uid AND b.notes IS NOT NULL AND b.notes LIKE 'http%'
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'first_photo')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 1) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_1')
    ON CONFLICT DO NOTHING;
  END IF;
  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 30) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_30')
    ON CONFLICT DO NOTHING;
  END IF;
  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 60) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_60')
    ON CONFLICT DO NOTHING;
  END IF;
  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 90) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_90')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid AND dl.log_date = d90 AND COALESCE(dl.submitted, false)
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'challenge_complete')
    ON CONFLICT DO NOTHING;
  END IF;

  IF longest >= 7 THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'streak_7')
    ON CONFLICT DO NOTHING;
  END IF;
  IF longest >= 14 THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'streak_14')
    ON CONFLICT DO NOTHING;
  END IF;
  IF longest >= 30 THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'streak_30')
    ON CONFLICT DO NOTHING;
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION public.sync_user_badges() TO authenticated;
REVOKE ALL ON FUNCTION public.longest_perfect_streak(uuid) FROM PUBLIC;

-- Realtime: run separately if needed (see migration-v11-enable-realtime.sql pattern):
--   ALTER PUBLICATION supabase_realtime ADD TABLE public.user_badges;

-- --- 3) Trigger: day_one on submit ------------------------------------------

CREATE OR REPLACE FUNCTION public.trg_daily_logs_award_day_one_badge()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF COALESCE(NEW.submitted, false) THEN
    INSERT INTO public.user_badges (user_id, badge_key)
    VALUES (NEW.user_id, 'day_one')
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_daily_logs_award_day_one_badge ON public.daily_logs;

CREATE TRIGGER trg_daily_logs_award_day_one_badge
  AFTER INSERT OR UPDATE OF submitted ON public.daily_logs
  FOR EACH ROW
  WHEN (COALESCE(NEW.submitted, false) = true)
  EXECUTE PROCEDURE public.trg_daily_logs_award_day_one_badge();

-- --- 4) Backfill ------------------------------------------------------------

INSERT INTO public.user_badges (user_id, badge_key)
SELECT DISTINCT dl.user_id, 'day_one'
FROM public.daily_logs dl
WHERE COALESCE(dl.submitted, false)
ON CONFLICT DO NOTHING;

-- ========== migration-v15-hidden-badges.sql ==========

-- ================================================
-- Migration v15: Hidden / secret badges (sync_user_badges)
-- Run in Supabase SQL Editor after v14. Safe to re-run.
-- Requires public.get_leaderboard() from base migration.sql.
-- ================================================

CREATE OR REPLACE FUNCTION public.sync_user_badges()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  uid uuid := auth.uid();
  d90 date := DATE '2026-06-27';
  longest int;
BEGIN
  IF uid IS NULL THEN
    RETURN;
  END IF;

  longest := public.longest_perfect_streak(uid);

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid AND COALESCE(dl.submitted, false)
    LIMIT 1
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'day_one')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid
      AND COALESCE(dl.submitted, false)
      AND COALESCE(dl.is_travel_day, false) = false
      AND dl.workout1 AND dl.workout2 AND dl.water AND dl.steps
      AND dl.no_sugar AND dl.reading AND dl.diet
    LIMIT 1
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'first_perfect_day')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.check_ins c
    WHERE c.user_id = uid AND c.photo_url IS NOT NULL AND TRIM(c.photo_url) <> ''
  ) OR EXISTS (
    SELECT 1 FROM public.body_stats b
    WHERE b.user_id = uid AND b.notes IS NOT NULL AND b.notes LIKE 'http%'
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'first_photo')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 1) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_1')
    ON CONFLICT DO NOTHING;
  END IF;
  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 30) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_30')
    ON CONFLICT DO NOTHING;
  END IF;
  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 60) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_60')
    ON CONFLICT DO NOTHING;
  END IF;
  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 90) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_90')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid AND dl.log_date = d90 AND COALESCE(dl.submitted, false)
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'challenge_complete')
    ON CONFLICT DO NOTHING;
  END IF;

  IF longest >= 7 THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'streak_7')
    ON CONFLICT DO NOTHING;
  END IF;
  IF longest >= 14 THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'streak_14')
    ON CONFLICT DO NOTHING;
  END IF;
  IF longest >= 30 THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'streak_30')
    ON CONFLICT DO NOTHING;
  END IF;

  -- --- Hidden badges --------------------------------------------------------

  -- Submitted a day that wasn’t “perfect” for that day type (still locked in)
  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid
      AND COALESCE(dl.submitted, false)
      AND (
        (
          NOT COALESCE(dl.is_travel_day, false)
          AND NOT (
            COALESCE(dl.workout1, false) AND COALESCE(dl.workout2, false)
            AND COALESCE(dl.water, false) AND COALESCE(dl.steps, false)
            AND COALESCE(dl.no_sugar, false) AND COALESCE(dl.reading, false) AND COALESCE(dl.diet, false)
          )
        )
        OR
        (
          COALESCE(dl.is_travel_day, false)
          AND NOT (
            COALESCE(dl.workout1, false) AND COALESCE(dl.water, false)
            AND COALESCE(dl.no_sugar, false) AND COALESCE(dl.reading, false) AND COALESCE(dl.diet, false)
          )
        )
      )
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'hidden_imperfect_day')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid
      AND COALESCE(dl.submitted, false)
      AND COALESCE(dl.is_travel_day, false)
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'hidden_travel_day')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.penalty_pot pp
    WHERE pp.user_id = uid AND COALESCE(pp.amount, 0) > 0
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'hidden_prize_pot')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.get_leaderboard() gl
    WHERE gl.user_id = uid AND gl.rank = 1
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'hidden_first_place')
    ON CONFLICT DO NOTHING;
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION public.sync_user_badges() TO authenticated;

-- ========== migration-v16-badge-collector-bonus.sql ==========

-- ================================================
-- Migration v16: +10 points when user has earned every badge (endgame collector bonus)
-- Requires: user_badges (v12/v14), get_leaderboard (base migration), all badge keys from app.
-- Run in Supabase SQL Editor. Safe to re-run.
-- ================================================

CREATE OR REPLACE FUNCTION public.badge_collector_bonus_points(p_user_id uuid)
RETURNS bigint
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH required AS (
    SELECT unnest(ARRAY[
      'day_one',
      'first_perfect_day',
      'first_photo',
      'milestone_checkin_1',
      'milestone_checkin_30',
      'milestone_checkin_60',
      'milestone_checkin_90',
      'challenge_complete',
      'streak_7',
      'streak_14',
      'streak_30',
      'hidden_imperfect_day',
      'hidden_travel_day',
      'hidden_prize_pot',
      'hidden_first_place'
    ]::text[]) AS badge_key
  ),
  matched AS (
    SELECT COUNT(DISTINCT r.badge_key)::bigint AS n
    FROM required r
    INNER JOIN public.user_badges ub
      ON ub.user_id = p_user_id AND ub.badge_key = r.badge_key
  )
  SELECT CASE
    WHEN (SELECT n FROM matched) = (SELECT COUNT(*)::bigint FROM required)
    THEN 10::bigint
    ELSE 0::bigint
  END;
$$;

REVOKE ALL ON FUNCTION public.badge_collector_bonus_points(uuid) FROM PUBLIC;

DROP FUNCTION IF EXISTS public.get_my_points();

CREATE OR REPLACE FUNCTION public.get_my_points()
RETURNS TABLE (
  total_points bigint,
  streak_bonus bigint,
  perfect_days bigint,
  current_streak integer,
  longest_streak integer,
  total_penalty decimal,
  badge_collector_bonus bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_collector bigint;
BEGIN
  v_collector := COALESCE(public.badge_collector_bonus_points(v_user_id), 0);

  RETURN QUERY
  WITH daily_agg AS (
    SELECT
      COALESCE(SUM(
        CASE
          WHEN dl.is_travel_day THEN
            (CASE WHEN dl.workout1 THEN 1 ELSE 0 END) +
            (CASE WHEN dl.water THEN 1 ELSE 0 END) +
            (CASE WHEN dl.no_sugar THEN 1 ELSE 0 END) +
            (CASE WHEN dl.reading THEN 1 ELSE 0 END) +
            (CASE WHEN dl.diet THEN 1 ELSE 0 END) -
            (
              (CASE WHEN NOT dl.workout1 THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.water THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.no_sugar THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.reading THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.diet THEN 3 ELSE 0 END)
            )
          ELSE
            (CASE WHEN dl.workout1 THEN 1 ELSE 0 END) +
            (CASE WHEN dl.workout2 THEN 1 ELSE 0 END) +
            (CASE WHEN dl.water THEN 1 ELSE 0 END) +
            (CASE WHEN dl.steps THEN 1 ELSE 0 END) +
            (CASE WHEN dl.no_sugar THEN 1 ELSE 0 END) +
            (CASE WHEN dl.reading THEN 1 ELSE 0 END) +
            (CASE WHEN dl.diet THEN 1 ELSE 0 END) +
            (CASE WHEN (dl.workout1 AND dl.workout2 AND dl.water AND dl.steps AND dl.no_sugar AND dl.reading AND dl.diet) THEN 3 ELSE 0 END) -
            (
              (CASE WHEN NOT dl.workout1 THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.workout2 THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.water THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.steps THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.no_sugar THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.reading THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.diet THEN 3 ELSE 0 END)
            )
        END
      ), 0)::bigint AS daily_sum,
      COUNT(*) FILTER (
        WHERE NOT dl.is_travel_day
          AND dl.workout1 AND dl.workout2 AND dl.water AND dl.steps
          AND dl.no_sugar AND dl.reading AND dl.diet
      )::bigint AS perfect_cnt
    FROM public.daily_logs dl
    WHERE dl.user_id = v_user_id
      AND COALESCE(dl.submitted, false) = true
  ),
  sb AS (
    SELECT COALESCE(public.streak_bonus_points(v_user_id), 0)::bigint AS streak_pts
  )
  SELECT
    (daily_agg.daily_sum + sb.streak_pts + v_collector)::bigint AS total_points,
    sb.streak_pts AS streak_bonus,
    daily_agg.perfect_cnt AS perfect_days,
    0::integer AS current_streak,
    0::integer AS longest_streak,
    COALESCE(
      (SELECT SUM(pp.amount) FROM public.penalty_pot pp WHERE pp.user_id = v_user_id),
      0
    )::decimal AS total_penalty,
    v_collector AS badge_collector_bonus
  FROM daily_agg
  CROSS JOIN sb;
END;
$$;

DROP FUNCTION IF EXISTS public.get_leaderboard();

CREATE OR REPLACE FUNCTION public.get_leaderboard()
RETURNS TABLE (
  user_id uuid,
  display_name text,
  avatar_emoji text,
  rank bigint,
  current_streak integer,
  is_on_fire boolean,
  penalty_contribution numeric
)
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
BEGIN
  RETURN QUERY
  WITH user_daily AS (
    SELECT
      dl.user_id,
      SUM(
        CASE
          WHEN dl.is_travel_day THEN
            (CASE WHEN dl.workout1 THEN 1 ELSE 0 END) +
            (CASE WHEN dl.water THEN 1 ELSE 0 END) +
            (CASE WHEN dl.no_sugar THEN 1 ELSE 0 END) +
            (CASE WHEN dl.reading THEN 1 ELSE 0 END) +
            (CASE WHEN dl.diet THEN 1 ELSE 0 END) -
            (
              (CASE WHEN NOT dl.workout1 THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.water THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.no_sugar THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.reading THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.diet THEN 3 ELSE 0 END)
            )
          ELSE
            (CASE WHEN dl.workout1 THEN 1 ELSE 0 END) +
            (CASE WHEN dl.workout2 THEN 1 ELSE 0 END) +
            (CASE WHEN dl.water THEN 1 ELSE 0 END) +
            (CASE WHEN dl.steps THEN 1 ELSE 0 END) +
            (CASE WHEN dl.no_sugar THEN 1 ELSE 0 END) +
            (CASE WHEN dl.reading THEN 1 ELSE 0 END) +
            (CASE WHEN dl.diet THEN 1 ELSE 0 END) +
            (CASE WHEN (dl.workout1 AND dl.workout2 AND dl.water AND dl.steps AND dl.no_sugar AND dl.reading AND dl.diet) THEN 3 ELSE 0 END) -
            (
              (CASE WHEN NOT dl.workout1 THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.workout2 THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.water THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.steps THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.no_sugar THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.reading THEN 3 ELSE 0 END) +
              (CASE WHEN NOT dl.diet THEN 3 ELSE 0 END)
            )
        END
      ) AS daily_sum,
      COUNT(*) FILTER (
        WHERE NOT dl.is_travel_day
          AND dl.workout1 AND dl.workout2 AND dl.water AND dl.steps
          AND dl.no_sugar AND dl.reading AND dl.diet
      ) AS perfect_days
    FROM public.daily_logs dl
    WHERE COALESCE(dl.submitted, false) = true
    GROUP BY dl.user_id
  ),
  user_points AS (
    SELECT
      ud.user_id,
      (
        COALESCE(ud.daily_sum, 0)
        + COALESCE(public.streak_bonus_points(ud.user_id), 0)
        + COALESCE(public.badge_collector_bonus_points(ud.user_id), 0)
      )::bigint AS total_points,
      ud.perfect_days
    FROM user_daily ud
  ),
  streaks AS (
    SELECT
      dl.user_id,
      COUNT(*) AS current_streak
    FROM public.daily_logs dl
    WHERE COALESCE(dl.submitted, false) = true
      AND dl.is_travel_day = false
      AND dl.workout1 = true AND dl.workout2 = true
      AND dl.water = true AND dl.steps = true
      AND dl.no_sugar = true AND dl.reading = true AND dl.diet = true
      AND dl.log_date >= (
        SELECT COALESCE(
          (SELECT MAX(d2.log_date) + INTERVAL '1 day'
           FROM public.daily_logs d2
           WHERE d2.user_id = dl.user_id
             AND d2.is_travel_day = false
             AND (
               NOT COALESCE(d2.submitted, false)
               OR NOT (d2.workout1 AND d2.workout2 AND d2.water AND d2.steps AND d2.no_sugar AND d2.reading AND d2.diet)
             )
          ),
          '2026-03-30'::date
        )
      )
    GROUP BY dl.user_id
  ),
  penalty_by_user AS (
    SELECT pp.user_id, COALESCE(SUM(pp.amount), 0)::numeric AS penalty_contribution
    FROM public.penalty_pot pp
    GROUP BY pp.user_id
  )
  SELECT
    p.id AS user_id,
    p.display_name,
    p.avatar_emoji,
    RANK() OVER (
      ORDER BY
        COALESCE(up.total_points, 0) DESC,
        COALESCE(up.perfect_days, 0) DESC,
        COALESCE(s.current_streak, 0) DESC
    ) AS rank,
    COALESCE(s.current_streak, 0)::integer AS current_streak,
    COALESCE(s.current_streak, 0) >= 3 AS is_on_fire,
    COALESCE(pb.penalty_contribution, 0)::numeric AS penalty_contribution
  FROM public.profiles p
  LEFT JOIN user_points up ON up.user_id = p.id
  LEFT JOIN streaks s ON s.user_id = p.id
  LEFT JOIN penalty_by_user pb ON pb.user_id = p.id
  WHERE p.pregnant_bailout = false
  ORDER BY
    COALESCE(up.total_points, 0) DESC,
    COALESCE(up.perfect_days, 0) DESC,
    COALESCE(s.current_streak, 0) DESC;
END;
$$;

-- ========== migration-v17-badge-gating-challenge-start.sql ==========

-- ================================================
-- Migration v17: Badge sync only after challenge start; first place from Day 10
-- Challenge start date uses America/Denver for DB badge rules (aligned with Mountain Time competitors).
-- Run in Supabase SQL Editor after v15/v16. Safe to re-run.
-- ================================================

CREATE OR REPLACE FUNCTION public.sync_user_badges()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  uid uuid := auth.uid();
  d90 date := DATE '2026-06-27';
  longest int;
  ch_start date := DATE '2026-03-30';
  today_denver date := (timezone('America/Denver', now()))::date;
  challenge_day int;
BEGIN
  IF uid IS NULL THEN
    RETURN;
  END IF;

  -- Before first challenge day (Denver): no badges
  IF today_denver < ch_start THEN
    RETURN;
  END IF;

  challenge_day := (today_denver - ch_start) + 1;

  longest := public.longest_perfect_streak(uid);

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid AND COALESCE(dl.submitted, false)
    LIMIT 1
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'day_one')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid
      AND COALESCE(dl.submitted, false)
      AND COALESCE(dl.is_travel_day, false) = false
      AND dl.workout1 AND dl.workout2 AND dl.water AND dl.steps
      AND dl.no_sugar AND dl.reading AND dl.diet
    LIMIT 1
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'first_perfect_day')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.check_ins c
    WHERE c.user_id = uid AND c.photo_url IS NOT NULL AND TRIM(c.photo_url) <> ''
  ) OR EXISTS (
    SELECT 1 FROM public.body_stats b
    WHERE b.user_id = uid AND b.notes IS NOT NULL AND b.notes LIKE 'http%'
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'first_photo')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 1) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_1')
    ON CONFLICT DO NOTHING;
  END IF;
  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 30) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_30')
    ON CONFLICT DO NOTHING;
  END IF;
  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 60) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_60')
    ON CONFLICT DO NOTHING;
  END IF;
  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 90) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_90')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid AND dl.log_date = d90 AND COALESCE(dl.submitted, false)
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'challenge_complete')
    ON CONFLICT DO NOTHING;
  END IF;

  IF longest >= 7 THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'streak_7')
    ON CONFLICT DO NOTHING;
  END IF;
  IF longest >= 14 THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'streak_14')
    ON CONFLICT DO NOTHING;
  END IF;
  IF longest >= 30 THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'streak_30')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid
      AND COALESCE(dl.submitted, false)
      AND (
        (
          NOT COALESCE(dl.is_travel_day, false)
          AND NOT (
            COALESCE(dl.workout1, false) AND COALESCE(dl.workout2, false)
            AND COALESCE(dl.water, false) AND COALESCE(dl.steps, false)
            AND COALESCE(dl.no_sugar, false) AND COALESCE(dl.reading, false) AND COALESCE(dl.diet, false)
          )
        )
        OR
        (
          COALESCE(dl.is_travel_day, false)
          AND NOT (
            COALESCE(dl.workout1, false) AND COALESCE(dl.water, false)
            AND COALESCE(dl.no_sugar, false) AND COALESCE(dl.reading, false) AND COALESCE(dl.diet, false)
          )
        )
      )
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'hidden_imperfect_day')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid
      AND COALESCE(dl.submitted, false)
      AND COALESCE(dl.is_travel_day, false)
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'hidden_travel_day')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.penalty_pot pp
    WHERE pp.user_id = uid AND COALESCE(pp.amount, 0) > 0
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'hidden_prize_pot')
    ON CONFLICT DO NOTHING;
  END IF;

  -- #1 on leaderboard only from challenge Day 10 onward (Denver calendar)
  IF challenge_day >= 10 AND EXISTS (
    SELECT 1 FROM public.get_leaderboard() gl
    WHERE gl.user_id = uid AND gl.rank = 1
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'hidden_first_place')
    ON CONFLICT DO NOTHING;
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION public.sync_user_badges() TO authenticated;

-- Day-one trigger: do not insert before challenge start (direct DB / edge cases)
CREATE OR REPLACE FUNCTION public.trg_daily_logs_award_day_one_badge()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF (timezone('America/Denver', now()))::date < DATE '2026-03-30' THEN
    RETURN NEW;
  END IF;
  IF COALESCE(NEW.submitted, false) THEN
    INSERT INTO public.user_badges (user_id, badge_key)
    VALUES (NEW.user_id, 'day_one')
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;

-- ========== migration-v18-penalty-pot-resync.sql ==========

-- ================================================
-- Migration v18: Rebuild penalty_pot from submitted daily_logs (repair + leaderboard truth)
-- Removes orphan penalty rows and reapplies apply_penalty_for_submitted_log for every
-- submitted day so partial/missed-task amounts stay aligned with daily_logs.
-- Safe to re-run.
-- ================================================

CREATE OR REPLACE FUNCTION public.resync_penalty_pot_from_daily_logs()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
SET row_security = off
AS $$
DECLARE
  r public.daily_logs%ROWTYPE;
BEGIN
  DELETE FROM public.penalty_pot pp
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.daily_logs dl
    WHERE dl.user_id = pp.user_id
      AND dl.log_date = pp.log_date
      AND COALESCE(dl.submitted, false) = true
  );

  FOR r IN
    SELECT * FROM public.daily_logs WHERE COALESCE(submitted, false) = true
  LOOP
    PERFORM public.apply_penalty_for_submitted_log(r);
  END LOOP;
END;
$$;

REVOKE ALL ON FUNCTION public.resync_penalty_pot_from_daily_logs() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.resync_penalty_pot_from_daily_logs() TO authenticated;

-- ========== migration-v19-penalty-trigger-rls.sql ==========

-- ================================================
-- Migration v19: Penalty sync must bypass RLS inside SECURITY DEFINER triggers
-- In some Postgres/Supabase setups, INSERT/DELETE on penalty_pot from trigger
-- can fail or no-op if row_security is evaluated for the wrong role.
-- Also apply to resync RPC. Safe to re-run.
-- ================================================

CREATE OR REPLACE FUNCTION public.apply_penalty_for_submitted_log(p_row public.daily_logs)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
SET row_security = off
AS $$
DECLARE
  missed text[] := '{}';
  n int := 0;
BEGIN
  IF NOT COALESCE(p_row.submitted, false) THEN
    DELETE FROM public.penalty_pot
    WHERE user_id = p_row.user_id AND log_date = p_row.log_date;
    RETURN;
  END IF;

  IF COALESCE(p_row.is_travel_day, false) THEN
    IF NOT COALESCE(p_row.workout1, false) THEN missed := array_append(missed, 'workout1'); n := n + 1; END IF;
    IF NOT COALESCE(p_row.water, false) THEN missed := array_append(missed, 'water'); n := n + 1; END IF;
    IF NOT COALESCE(p_row.no_sugar, false) THEN missed := array_append(missed, 'no_sugar'); n := n + 1; END IF;
    IF NOT COALESCE(p_row.reading, false) THEN missed := array_append(missed, 'reading'); n := n + 1; END IF;
    IF NOT COALESCE(p_row.diet, false) THEN missed := array_append(missed, 'diet'); n := n + 1; END IF;
  ELSE
    IF NOT COALESCE(p_row.workout1, false) THEN missed := array_append(missed, 'workout1'); n := n + 1; END IF;
    IF NOT COALESCE(p_row.workout2, false) THEN missed := array_append(missed, 'workout2'); n := n + 1; END IF;
    IF NOT COALESCE(p_row.water, false) THEN missed := array_append(missed, 'water'); n := n + 1; END IF;
    IF NOT COALESCE(p_row.steps, false) THEN missed := array_append(missed, 'steps'); n := n + 1; END IF;
    IF NOT COALESCE(p_row.no_sugar, false) THEN missed := array_append(missed, 'no_sugar'); n := n + 1; END IF;
    IF NOT COALESCE(p_row.reading, false) THEN missed := array_append(missed, 'reading'); n := n + 1; END IF;
    IF NOT COALESCE(p_row.diet, false) THEN missed := array_append(missed, 'diet'); n := n + 1; END IF;
  END IF;

  DELETE FROM public.penalty_pot
  WHERE user_id = p_row.user_id AND log_date = p_row.log_date;

  IF n > 0 THEN
    INSERT INTO public.penalty_pot (user_id, log_date, amount, missed_tasks)
    VALUES (p_row.user_id, p_row.log_date, (n)::decimal(6,2), missed);
  END IF;
END;
$$;

CREATE OR REPLACE FUNCTION public.trg_daily_logs_sync_penalty()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
SET row_security = off
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM public.penalty_pot
    WHERE user_id = OLD.user_id AND log_date = OLD.log_date;
    RETURN OLD;
  END IF;
  PERFORM public.apply_penalty_for_submitted_log(NEW);
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.resync_penalty_pot_from_daily_logs()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
SET row_security = off
AS $$
DECLARE
  r public.daily_logs%ROWTYPE;
BEGIN
  DELETE FROM public.penalty_pot pp
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.daily_logs dl
    WHERE dl.user_id = pp.user_id
      AND dl.log_date = pp.log_date
      AND COALESCE(dl.submitted, false) = true
  );

  FOR r IN
    SELECT * FROM public.daily_logs WHERE COALESCE(submitted, false) = true
  LOOP
    PERFORM public.apply_penalty_for_submitted_log(r);
  END LOOP;
END;
$$;

-- ========== migration-v20-hidden-badges-after-day90.sql ==========

-- ================================================
-- Migration v20: Secret (hidden) badges only after Day 90 is locked in
-- Retro history edits can change standings, penalties, and imperfect days until the challenge
-- is finished — then hidden_imperfect_day, hidden_travel_day, hidden_prize_pot, hidden_first_place
-- are evaluated in sync_user_badges (after challenge_complete for day 90).
-- Safe to re-run.
-- ================================================

CREATE OR REPLACE FUNCTION public.sync_user_badges()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  uid uuid := auth.uid();
  d90 date := DATE '2026-06-27';
  longest int;
  ch_start date := DATE '2026-03-30';
  today_denver date := (timezone('America/Denver', now()))::date;
  challenge_day int;
BEGIN
  IF uid IS NULL THEN
    RETURN;
  END IF;

  IF today_denver < ch_start THEN
    RETURN;
  END IF;

  challenge_day := (today_denver - ch_start) + 1;

  longest := public.longest_perfect_streak(uid);

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid AND COALESCE(dl.submitted, false)
    LIMIT 1
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'day_one')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid
      AND COALESCE(dl.submitted, false)
      AND COALESCE(dl.is_travel_day, false) = false
      AND dl.workout1 AND dl.workout2 AND dl.water AND dl.steps
      AND dl.no_sugar AND dl.reading AND dl.diet
    LIMIT 1
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'first_perfect_day')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.check_ins c
    WHERE c.user_id = uid AND c.photo_url IS NOT NULL AND TRIM(c.photo_url) <> ''
  ) OR EXISTS (
    SELECT 1 FROM public.body_stats b
    WHERE b.user_id = uid AND b.notes IS NOT NULL AND b.notes LIKE 'http%'
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'first_photo')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 1) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_1')
    ON CONFLICT DO NOTHING;
  END IF;
  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 30) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_30')
    ON CONFLICT DO NOTHING;
  END IF;
  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 60) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_60')
    ON CONFLICT DO NOTHING;
  END IF;
  IF EXISTS (SELECT 1 FROM public.check_ins WHERE user_id = uid AND day_number = 90) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'milestone_checkin_90')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid AND dl.log_date = d90 AND COALESCE(dl.submitted, false)
  ) THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'challenge_complete')
    ON CONFLICT DO NOTHING;
  END IF;

  IF longest >= 7 THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'streak_7')
    ON CONFLICT DO NOTHING;
  END IF;
  IF longest >= 14 THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'streak_14')
    ON CONFLICT DO NOTHING;
  END IF;
  IF longest >= 30 THEN
    INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'streak_30')
    ON CONFLICT DO NOTHING;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.daily_logs dl
    WHERE dl.user_id = uid AND dl.log_date = d90 AND COALESCE(dl.submitted, false)
  ) THEN
    IF EXISTS (
      SELECT 1 FROM public.daily_logs dl
      WHERE dl.user_id = uid
        AND COALESCE(dl.submitted, false)
        AND (
          (
            NOT COALESCE(dl.is_travel_day, false)
            AND NOT (
              COALESCE(dl.workout1, false) AND COALESCE(dl.workout2, false)
              AND COALESCE(dl.water, false) AND COALESCE(dl.steps, false)
              AND COALESCE(dl.no_sugar, false) AND COALESCE(dl.reading, false) AND COALESCE(dl.diet, false)
            )
          )
          OR
          (
            COALESCE(dl.is_travel_day, false)
            AND NOT (
              COALESCE(dl.workout1, false) AND COALESCE(dl.water, false)
              AND COALESCE(dl.no_sugar, false) AND COALESCE(dl.reading, false) AND COALESCE(dl.diet, false)
            )
          )
        )
    ) THEN
      INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'hidden_imperfect_day')
      ON CONFLICT DO NOTHING;
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.daily_logs dl
      WHERE dl.user_id = uid
        AND COALESCE(dl.submitted, false)
        AND COALESCE(dl.is_travel_day, false)
    ) THEN
      INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'hidden_travel_day')
      ON CONFLICT DO NOTHING;
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.penalty_pot pp
      WHERE pp.user_id = uid AND COALESCE(pp.amount, 0) > 0
    ) THEN
      INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'hidden_prize_pot')
      ON CONFLICT DO NOTHING;
    END IF;

    IF challenge_day >= 10 AND EXISTS (
      SELECT 1 FROM public.get_leaderboard() gl
      WHERE gl.user_id = uid AND gl.rank = 1
    ) THEN
      INSERT INTO public.user_badges (user_id, badge_key) VALUES (uid, 'hidden_first_place')
      ON CONFLICT DO NOTHING;
    END IF;
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION public.sync_user_badges() TO authenticated;

-- ========== migration-v21-checkin-before-tasks.sql ==========

-- Block turning on any daily task until the user has a milestone check-in with weight
-- for that challenge day (Days 1, 30, 60, 90). Matches app CHALLENGE_START (2026-03-30).

CREATE OR REPLACE FUNCTION public.daily_log_challenge_day(p_log_date date)
RETURNS integer
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT (p_log_date - date '2026-03-30')::integer + 1;
$$;

CREATE OR REPLACE FUNCTION public.enforce_checkin_before_tasks()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  d integer;
  tasks_on boolean;
BEGIN
  d := public.daily_log_challenge_day(NEW.log_date);
  IF d < 1 OR d > 90 THEN
    RETURN NEW;
  END IF;
  IF d NOT IN (1, 30, 60, 90) THEN
    RETURN NEW;
  END IF;

  tasks_on := COALESCE(NEW.workout1, false)
    OR COALESCE(NEW.workout2, false)
    OR COALESCE(NEW.water, false)
    OR COALESCE(NEW.steps, false)
    OR COALESCE(NEW.no_sugar, false)
    OR COALESCE(NEW.reading, false)
    OR COALESCE(NEW.diet, false);

  IF NOT tasks_on THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.check_ins c
    WHERE c.user_id = NEW.user_id
      AND c.day_number = d
      AND c.weight IS NOT NULL
  ) THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'Milestone check-in (weight) required before logging tasks on challenge day %', d
    USING ERRCODE = 'check_violation';
END;
$$;

DROP TRIGGER IF EXISTS trg_enforce_checkin_before_tasks ON public.daily_logs;

CREATE TRIGGER trg_enforce_checkin_before_tasks
  BEFORE INSERT OR UPDATE OF workout1, workout2, water, steps, no_sugar, reading, diet
  ON public.daily_logs
  FOR EACH ROW
  EXECUTE FUNCTION public.enforce_checkin_before_tasks();

-- ========== storage.sql ==========

-- Run this in Supabase SQL Editor to create the photo storage bucket

-- Create storage bucket for check-in photos
insert into storage.buckets (id, name, public)
values ('checkin-photos', 'checkin-photos', true)
on conflict (id) do nothing;

-- Allow authenticated users to upload their own photos
create policy "Users can upload own photos"
on storage.objects for insert
to authenticated
with check (
  bucket_id = 'checkin-photos'
  and (storage.foldername(name))[1] = auth.uid()::text
);

-- Allow authenticated users to view all photos (for leaderboard avatars etc)
create policy "Anyone can view photos"
on storage.objects for select
to authenticated
using (bucket_id = 'checkin-photos');

-- Allow users to update/delete their own photos
create policy "Users can update own photos"
on storage.objects for update
to authenticated
using (
  bucket_id = 'checkin-photos'
  and (storage.foldername(name))[1] = auth.uid()::text
);

create policy "Users can delete own photos"
on storage.objects for delete
to authenticated
using (
  bucket_id = 'checkin-photos'
  and (storage.foldername(name))[1] = auth.uid()::text
);
